+/**
+ * FAQItem – manages a single disclosure widget.
+ * Mirrors a React component's encapsulated state & behaviour in vanilla JS.
+ */
+class FAQItem {
+  constructor(exampleEl) {
+    this.trigger = exampleEl.querySelector(".faq-trigger");
+    this.details = exampleEl.querySelector(".details");
+
+    if (!this.trigger || !this.details) return;
+
+    this.isOpen = false;
+    this._bindEvents();
+  }
+
+  _bindEvents() {
+    this.trigger.addEventListener("click", () => this.toggle());
+    this.trigger.addEventListener("keydown", (e) => {
+      if (e.key === "Enter" || e.key === " ") {
+        e.preventDefault();
+        this.toggle();
+      }
+    });
+  }
+
+  toggle() {
+    this.isOpen ? this.close() : this.open();
+  }
+
+  open() {
+    this.isOpen = true;
+    this.trigger.setAttribute("aria-expanded", "true");
+    this.details.setAttribute("aria-hidden", "false");
+  }
+
+  close() {
+    this.isOpen = false;
+    this.trigger.setAttribute("aria-expanded", "false");
+    this.details.setAttribute("aria-hidden", "true");
+  }
+}
+
+/**
+ * FAQList – initialises all FAQItem components on the page.
+ * Analogous to a React parent component rendering a list of children.
+ */
+class FAQList {
+  constructor() {
+    document.querySelectorAll(".example").forEach((el) => new FAQItem(el));
+  }
+}
+
+document.addEventListener("DOMContentLoaded", () => new FAQList());
